using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace E.DataLinq.Web.Razor;

/// <summary>
/// de: Hilfsfunktionen für das Filtern/Sortieren von Records (IDictionary&lt;string, object&gt;) mit LINQ. Wird vom PDF-Editor (Daten-Bereich) generiert.
/// en: Helper functions for filtering/sorting records (IDictionary&lt;string, object&gt;) with LINQ. Used by code generated by the PDF editor (data section).
/// </summary>
public static class DataLinqRecordFilter
{
    public static object Get(IDictionary<string, object> record, string column)
    {
        if (record == null || column == null) return null;
        if (record.TryGetValue(column, out var value)) return value;

        var key = record.Keys.FirstOrDefault(k => string.Equals(k, column, StringComparison.OrdinalIgnoreCase));
        return key != null ? record[key] : null;
    }

    public static bool IsNull(object value)
        => value == null || value is DBNull || (value is string s && s.Length == 0);

    public static int Compare(object a, object b)
    {
        if (IsNull(a) && IsNull(b)) return 0;
        if (IsNull(a)) return -1;
        if (IsNull(b)) return 1;

        if (TryDouble(a, out var da) && TryDouble(b, out var db)) return da.CompareTo(db);
        if (TryDate(a, out var ta) && TryDate(b, out var tb)) return ta.CompareTo(tb);
        if (a is bool ba && TryBool(b, out var bb)) return ba.CompareTo(bb);

        return string.Compare(Convert.ToString(a, CultureInfo.InvariantCulture),
                              Convert.ToString(b, CultureInfo.InvariantCulture),
                              StringComparison.OrdinalIgnoreCase);
    }

    public static bool Eq(object a, object b) => Compare(a, b) == 0;

    public static bool Contains(object value, string part)
        => !IsNull(value) && Convert.ToString(value, CultureInfo.InvariantCulture).IndexOf(part ?? "", StringComparison.OrdinalIgnoreCase) >= 0;

    public static bool StartsWith(object value, string part)
        => !IsNull(value) && Convert.ToString(value, CultureInfo.InvariantCulture).StartsWith(part ?? "", StringComparison.OrdinalIgnoreCase);

    public static bool EndsWith(object value, string part)
        => !IsNull(value) && Convert.ToString(value, CultureInfo.InvariantCulture).EndsWith(part ?? "", StringComparison.OrdinalIgnoreCase);

    public static bool In(object value, params object[] values)
        => values != null && values.Any(v => Eq(value, v));

    public static IComparer<object> Comparer { get; } = Comparer<object>.Create(Compare);

    public static IEqualityComparer<object> EqualityComparer { get; } = new ObjectEqualityComparer();

    public static IDictionary<string, object> Project(IDictionary<string, object> record, params string[] columns)
    {
        var result = new Dictionary<string, object>();
        foreach (var column in columns ?? Array.Empty<string>())
        {
            result[column] = Get(record, column);
        }
        return result;
    }

    public static string Key(IDictionary<string, object> record, params string[] columns)
    {
        return string.Join("\u001f", (columns ?? Array.Empty<string>()).Select(column =>
        {
            var value = Get(record, column);
            return IsNull(value) ? string.Empty : Convert.ToString(value, CultureInfo.InvariantCulture).ToLowerInvariant();
        }));
    }

    public static DateTime Date(string value)
    {
        return DateTime.Parse(value, CultureInfo.InvariantCulture);
    }

    public static IDictionary<string, object>[] RequireRows(IDictionary<string, object>[] records, string errorMessage)
    {
        if (records == null || records.Length == 0)
        {
            throw new Exception(string.IsNullOrWhiteSpace(errorMessage) ? "DataLinq: no records found" : errorMessage);
        }
        return records;
    }

    private static bool TryDouble(object o, out double d)
    {
        switch (o)
        {
            case double x: d = x; return true;
            case float x: d = x; return true;
            case decimal x: d = (double)x; return true;
            case int x: d = x; return true;
            case long x: d = x; return true;
            case short x: d = x; return true;
            case byte x: d = x; return true;
            case string s:
                return double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out d);
        }
        d = 0;
        return false;
    }

    private static bool TryDate(object o, out DateTime t)
    {
        if (o is DateTime dt) { t = dt; return true; }
        if (o is DateTimeOffset dto) { t = dto.DateTime; return true; }
        if (o is string s)
        {
            return DateTime.TryParse(s, CultureInfo.InvariantCulture, DateTimeStyles.None, out t)
                || DateTime.TryParse(s, CultureInfo.GetCultureInfo("de-DE"), DateTimeStyles.None, out t);
        }
        t = default;
        return false;
    }

    private static bool TryBool(object o, out bool b)
    {
        if (o is bool x) { b = x; return true; }
        return bool.TryParse(Convert.ToString(o, CultureInfo.InvariantCulture), out b);
    }

    private class ObjectEqualityComparer : IEqualityComparer<object>
    {
        public new bool Equals(object x, object y) => Eq(x, y);

        public int GetHashCode(object obj)
        {
            if (IsNull(obj)) return 0;
            if (TryDouble(obj, out var d)) return d.GetHashCode();
            return Convert.ToString(obj, CultureInfo.InvariantCulture).ToLowerInvariant().GetHashCode();
        }
    }
}
